<?php require_once dirname(__DIR__) . '/app/config.php';if($_SERVER['REQUEST_METHOD']==='POST'){require_login();csrf_check();$content=trim($_POST['content']??'');if($content!==''){ $st=$pdo->prepare("INSERT INTO posts(user_id,content,status) VALUES(?,?,'published')");$st->execute([user()['id'],$content]);flash('success','Bài chia sẻ đã được đăng.');}redirect('community.php');}$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT p.*,u.name FROM posts p JOIN users u ON u.id=p.user_id WHERE p.status='published' AND p.content LIKE ? ORDER BY p.created_at DESC");$st->execute(['%'.$q.'%']);$posts=$st->fetchAll();header_html('Cộng đồng');?><div class="row g-4"><div class="col-lg-8"><h1 class="fw-bold">Cộng đồng sinh viên CNTT</h1><?php if(user()):?><form method="post" class="card p-3 border-0 shadow-sm mb-4"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><textarea class="form-control mb-3" name="content" rows="3" maxlength="5000" placeholder="Chia sẻ tài liệu, kinh nghiệm hoặc câu hỏi..." required></textarea><button class="btn btn-primary align-self-end">Đăng bài</button></form><?php else:?><div class="alert alert-info">Đăng nhập để chia sẻ cùng cộng đồng. <a href="auth.php">Đăng nhập</a></div><?php endif;?><form class="input-group mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Tìm bài viết..."><button class="btn btn-outline-primary">Tìm</button></form><?php foreach($posts as $p):?><article class="card border-0 shadow-sm p-3 mb-3"><div class="d-flex justify-content-between"><strong><i class="fa fa-user-circle text-primary me-2"></i><?=e($p['name'])?></strong><small class="text-muted"><?=e($p['created_at'])?></small></div><p class="mb-0 mt-3"><?=nl2br(e($p['content']))?></p></article><?php endforeach;?><?php if(!$posts):?><div class="empty-state">Chưa có bài viết phù hợp.</div><?php endif;?></div><div class="col-lg-4"><div class="card p-4 border-0 shadow-sm"><h5>Quy định cộng đồng</h5><p class="text-muted mb-0">Tôn trọng thành viên, chia sẻ nội dung có nguồn gốc rõ ràng và không đăng tài liệu vi phạm bản quyền.</p></div></div></div><?php footer_html();?>
